package edu.bjfu.eldercare;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.util.*;import java.time.*;import static edu.bjfu.eldercare.Store.id;
@Service public class CareService {
 private final Store db;private final Crypto crypto;
 public CareService(Store d,Crypto c){db=d;crypto=c;}
 private void actor(Auth.User u){db.update("SET @actor=?",u.id()+":"+u.name());}
 public void elderScope(Auth.User u,long elder){var e=db.one("SELECT * FROM elder WHERE id=?",elder);
 boolean ok=switch(u.role()){case "FAMILY"->db.count("SELECT COUNT(*) FROM guardian WHERE elder_id=? AND account_id=?",elder,u.id())>0;case "CAREGIVER"->db.count("SELECT COUNT(*) FROM dispatch d JOIN service_order o ON o.id=d.order_id JOIN caregiver c ON c.id=d.caregiver_id WHERE o.elder_id=? AND c.account_id=?",elder,u.id())>0;default->id(e,"community_id")==u.community();};if(!ok)throw new Forbidden();}
 private Map<String,Object> orderScope(Auth.User u,long order){var o=db.one("SELECT * FROM service_order WHERE id=? FOR UPDATE",order);elderScope(u,id(o,"elder_id"));if(u.role().equals("CAREGIVER")&&db.count("SELECT COUNT(*) FROM dispatch d JOIN caregiver c ON c.id=d.caregiver_id WHERE d.order_id=? AND c.account_id=? AND d.status IN('WAITING','ACCEPTED')",order,u.id())==0)throw new Forbidden();return o;}
 private void workerScope(Auth.User u,long worker){var c=db.one("SELECT c.*,a.community_id FROM caregiver c JOIN account a ON a.id=c.account_id WHERE c.id=?",worker);if(u.role().equals("MANAGER")){if(u.organization()==null||id(c,"organization_id")!=u.organization())throw new Forbidden();}else if(id(c,"community_id")!=u.community())throw new Forbidden();}
 private static String s(Map<String,Object> m,String k){Object v=m.get(k);if(v==null||v.toString().isBlank())throw new Rule("缺少字段: "+k);return v.toString();}
 private static long n(Map<String,Object> m,String k){try{return Long.parseLong(s(m,k));}catch(NumberFormatException e){throw new Rule("编号无效: "+k);}}
 private static boolean b(Map<String,Object> m,String k){return Boolean.parseBoolean(s(m,k));}
 @Transactional public Object execute(Auth.User u,String action,Map<String,Object> m){actor(u);long x;
 switch(action){
 case "elder.create": Auth.role(u,"ADMIN");return db.insert("INSERT INTO elder(name,identity_hash,identity_cipher,birth_date,address,community_id) VALUES(?,?,?,?,?,?)",s(m,"name"),crypto.hash(s(m,"identity")),crypto.encrypt(s(m,"identity")),s(m,"birthDate"),s(m,"address"),u.community());
 case "guardian.create":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);if(db.count("SELECT COUNT(*) FROM account WHERE id=? AND role='FAMILY' AND community_id=?",n(m,"accountId"),u.community())!=1)throw new Rule("家属账号范围错误");return db.insert("INSERT INTO guardian(elder_id,account_id,relation_name,phone_cipher) VALUES(?,?,?,?)",x,n(m,"accountId"),s(m,"relation"),crypto.encrypt(s(m,"phone")));
 case "credential.create":Auth.role(u,"MANAGER");x=n(m,"caregiverId");workerScope(u,x);return db.insert("INSERT INTO credential(caregiver_id,item_id,certificate_no,certificate_level,valid_from,valid_until) VALUES(?,?,?,?,?,?)",x,n(m,"itemId"),s(m,"certificateNo"),s(m,"level"),s(m,"validFrom"),s(m,"validUntil"));
 case "caregiver.status":Auth.role(u,"MANAGER");x=n(m,"caregiverId");workerScope(u,x);return db.update("UPDATE caregiver SET status=? WHERE id=?",s(m,"status"),x);
 case "device.create":Auth.role(u,"ADMIN");return db.insert("INSERT INTO device(serial_no,type_name,location_note) VALUES(?,?,?)",s(m,"serial"),s(m,"type"),s(m,"location"));
 case "elder.update":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);return db.update("UPDATE elder SET address=? WHERE id=?",s(m,"address"),x);
 case "elder.deactivate":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);return db.update("UPDATE elder SET status='INACTIVE' WHERE id=?",x);
 case "assessment.create":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);return db.insert("INSERT INTO assessment(elder_id,scale_name,score,ability_level,assessor_id,assessed_at,valid_until) VALUES(?,?,?,?,?,NOW(),?)",x,s(m,"scale"),n(m,"score"),s(m,"level"),u.id(),s(m,"validUntil"));
 case "plan.create":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);workerScope(u,n(m,"caregiverId"));long plan=db.insert("INSERT INTO care_plan(elder_id,assessment_id,bundle_id,caregiver_id,starts_at,ends_at) VALUES(?,?,?,?,?,?)",x,n(m,"assessmentId"),n(m,"bundleId"),n(m,"caregiverId"),s(m,"startsAt"),s(m,"endsAt"));db.update("INSERT INTO plan_item(plan_id,item_id,weekly_frequency) SELECT ?,item_id,weekly_frequency FROM bundle_item WHERE bundle_id=?",plan,n(m,"bundleId"));return plan;
 case "order.create":Auth.role(u,"ADMIN","FAMILY");x=n(m,"elderId");elderScope(u,x);var e=db.one("SELECT * FROM elder WHERE id=?",x);var item=db.one("SELECT * FROM service_item WHERE id=?",n(m,"itemId"));var start=LocalDateTime.parse(s(m,"startsAt"));var end=start.plusMinutes(id(item,"duration_minutes"));if(start.isBefore(LocalDateTime.now()))throw new Rule("预约时间必须在未来");return db.insert("INSERT INTO service_order(elder_id,item_id,community_id,starts_at,ends_at,address,channel,amount,created_by) VALUES(?,?,?,?,?,?,?,?,?)",x,item.get("id"),e.get("community_id"),start,end,e.get("address"),u.role().equals("FAMILY")?"FAMILY":"COMMUNITY",item.get("price"),u.id());
 case "order.assign":Auth.role(u,"ADMIN");x=n(m,"orderId");orderScope(u,x);db.call("assign_order",x,n(m,"shiftId"),s(m,"reason"));return "派单成功";
 case "order.accept":Auth.role(u,"CAREGIVER");x=n(m,"orderId");var o=orderScope(u,x);if(!o.get("status").equals("ASSIGNED"))throw new Rule("订单不可接单");var d=db.one("SELECT * FROM dispatch WHERE order_id=? AND status='WAITING'",x);db.jdbc.update("CALL assert_order(?,?,?,?,?)",o.get("elder_id"),o.get("item_id"),o.get("community_id"),o.get("starts_at"),o.get("ends_at"));if(db.count("SELECT COUNT(*) FROM credential WHERE caregiver_id=? AND item_id=? AND valid_from<=NOW() AND valid_until>=GREATEST(NOW(),?)",d.get("caregiver_id"),o.get("item_id"),o.get("ends_at"))==0)throw new Rule("证书已失效");db.update("UPDATE dispatch SET status='ACCEPTED',accepted_at=NOW() WHERE id=?",d.get("id"));return db.update("UPDATE service_order SET status='ACCEPTED' WHERE id=?",x);
 case "order.checkin":Auth.role(u,"CAREGIVER");x=n(m,"orderId");o=orderScope(u,x);if(!o.get("status").equals("ACCEPTED"))throw new Rule("订单未接单");d=db.one("SELECT * FROM dispatch WHERE order_id=? AND status='ACCEPTED'",x);db.insert("INSERT INTO attendance(dispatch_id,check_in,location_note,fence_ok) VALUES(?,NOW(),?,?)",d.get("id"),s(m,"location"),b(m,"fenceOk"));return db.update("UPDATE service_order SET status='SERVING' WHERE id=?",x);
 case "order.finish":Auth.role(u,"CAREGIVER");x=n(m,"orderId");o=orderScope(u,x);if(!o.get("status").equals("SERVING"))throw new Rule("订单不在服务中");d=db.one("SELECT * FROM dispatch WHERE order_id=? AND status='ACCEPTED'",x);db.update("UPDATE attendance SET check_out=NOW() WHERE dispatch_id=?",d.get("id"));db.call("verify_hours",d.get("id"));db.insert("INSERT INTO service_record(dispatch_id,notes) VALUES(?,?)",d.get("id"),s(m,"notes"));db.update("UPDATE dispatch SET status='FINISHED' WHERE id=?",d.get("id"));return db.update("UPDATE service_order SET status='CONFIRM' WHERE id=?",x);
 case "order.confirm":Auth.role(u,"FAMILY");x=n(m,"orderId");o=orderScope(u,x);if(!o.get("status").equals("CONFIRM"))throw new Rule("订单非待确认");db.update("UPDATE service_record r JOIN dispatch d ON d.id=r.dispatch_id SET r.confirmed_by=?,r.confirmed_at=NOW(),r.confirmation=? WHERE d.order_id=? AND d.status='FINISHED'",u.id(),s(m,"confirmation"),x);return db.update("UPDATE service_order SET status='COMPLETED' WHERE id=?",x);
 case "order.cancel":Auth.role(u,"ADMIN","FAMILY");x=n(m,"orderId");o=orderScope(u,x);if(!Set.of("PENDING","ASSIGNED","ACCEPTED").contains(o.get("status")))throw new Rule("当前状态不能取消");var ds=db.rows("SELECT * FROM dispatch WHERE order_id=? AND active_order IS NOT NULL",x);for(var z:ds){db.update("UPDATE dispatch SET status='REJECTED',reason=? WHERE id=?",s(m,"reason"),z.get("id"));db.update("UPDATE shift SET used_count=used_count-1 WHERE id=?",z.get("shift_id"));}return db.update("UPDATE service_order SET status='CANCELLED' WHERE id=?",x);
 case "complaint.create":Auth.role(u,"FAMILY");x=n(m,"orderId");orderScope(u,x);return db.insert("INSERT INTO complaint(order_id,account_id,rating,content) VALUES(?,?,?,?)",x,u.id(),n(m,"rating"),s(m,"content"));
 case "shift.create":Auth.role(u,"MANAGER","ADMIN");x=n(m,"caregiverId");workerScope(u,x);return db.insert("INSERT INTO shift(caregiver_id,starts_at,ends_at,capacity) VALUES(?,?,?,?)",x,s(m,"startsAt"),s(m,"endsAt"),n(m,"capacity"));
 case "shift.delete":Auth.role(u,"MANAGER");x=n(m,"shiftId");var sh=db.one("SELECT * FROM shift WHERE id=? FOR UPDATE",x);workerScope(u,id(sh,"caregiver_id"));if(id(sh,"used_count")!=0)throw new Rule("已被使用的班次不能删除");return db.update("DELETE FROM shift WHERE id=? AND starts_at>NOW()",x);
 case "hours.review":Auth.role(u,"MANAGER");x=n(m,"attendanceId");var a=db.one("SELECT a.*,d.caregiver_id FROM attendance a JOIN dispatch d ON d.id=a.dispatch_id WHERE a.id=? FOR UPDATE",x);workerScope(u,id(a,"caregiver_id"));if(!a.get("status").equals("REVIEW"))throw new Rule("非待复核工时");return db.update("UPDATE attendance SET status=?,effective_minutes=IF(?,TIMESTAMPDIFF(MINUTE,check_in,check_out),0),reviewer_id=?,review_reason=? WHERE id=?",b(m,"approve")?"VALID":"INVALID",b(m,"approve"),u.id(),s(m,"reason"),x);
 case "device.bind":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);long device=n(m,"deviceId");db.one("SELECT * FROM device WHERE id=? FOR UPDATE",device);var bindings=db.rows("SELECT * FROM device_binding WHERE device_id=? AND unbound_at IS NULL",device);for(var z:bindings)elderScope(u,id(z,"elder_id"));db.update("UPDATE device_binding SET unbound_at=NOW() WHERE device_id=? AND unbound_at IS NULL",device);return db.insert("INSERT INTO device_binding(device_id,elder_id,bound_at) VALUES(?,?,NOW())",device,x);
 case "vital.upload":Auth.role(u,"ADMIN");var samples=m.get("samples");if(!(samples instanceof List<?> list)||list.size()>500)throw new Rule("samples 必须为不超过 500 条的数组");for(Object v:list){@SuppressWarnings("unchecked") var z=(Map<String,Object>)v;var bind=db.one("SELECT * FROM device_binding WHERE id=?",n(z,"bindingId"));elderScope(u,id(bind,"elder_id"));db.insert("INSERT INTO vital(binding_id,metric_rule_id,sample_key,collected_at,metric_value,source) VALUES(?,?,?,?,?,?)",n(z,"bindingId"),n(z,"metricId"),s(z,"sampleKey"),s(z,"collectedAt"),s(z,"value"),"SIMULATOR");}return list.size();
 case "event.respond":Auth.role(u,"ADMIN","CAREGIVER");x=n(m,"eventId");var event=db.one("SELECT * FROM emergency WHERE id=? FOR UPDATE",x);elderScope(u,id(event,"elder_id"));if(!Set.of("OPEN","UNCONFIRMED").contains(event.get("status")))throw new Rule("事件已响应或关闭");return db.update("UPDATE emergency SET status='RESPONDED',responded_by=?,responded_at=NOW() WHERE id=?",u.id(),x);
 case "event.close":Auth.role(u,"ADMIN","CAREGIVER");x=n(m,"eventId");event=db.one("SELECT * FROM emergency WHERE id=? FOR UPDATE",x);elderScope(u,id(event,"elder_id"));if(!event.get("status").equals("RESPONDED"))throw new Rule("事件尚未响应");return db.update("UPDATE emergency SET status='CLOSED',arrived_at=NOW(),result=? WHERE id=?",s(m,"result"),x);
 case "claim.submit":Auth.role(u,"ADMIN");x=n(m,"elderId");elderScope(u,x);try{db.call("submit_claim",x,n(m,"policyId"),s(m,"period"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(m.get("orderIds")));}catch(com.fasterxml.jackson.core.JsonProcessingException ex){throw new Rule("订单列表无效");}return "申报成功";
 case "claim.review":Auth.role(u,"STREET","REGULATOR");x=n(m,"claimId");var cl=db.one("SELECT * FROM claim WHERE id=? FOR UPDATE",x);elderScope(u,id(cl,"elder_id"));String required=u.role().equals("STREET")?"SUBMITTED":"STREET_APPROVED";if(!cl.get("status").equals(required))throw new Rule("审核阶段不匹配");boolean approve=b(m,"approve");db.insert("INSERT INTO claim_review(claim_id,reviewer_id,stage,decision,reason) VALUES(?,?,?,?,?)",x,u.id(),u.role(),approve?"APPROVE":"REJECT",s(m,"reason"));return db.update("UPDATE claim SET status=? WHERE id=?",approve?(u.role().equals("STREET")?"STREET_APPROVED":"APPROVED"):"REJECTED",x);
 case "claim.pay":Auth.role(u,"REGULATOR");x=n(m,"claimId");cl=db.one("SELECT * FROM claim WHERE id=? FOR UPDATE",x);elderScope(u,id(cl,"elder_id"));if(!cl.get("status").equals("APPROVED"))throw new Rule("申报尚未审批完成");db.insert("INSERT INTO payment(claim_id,reference_no,amount) VALUES(?,?,?)",x,s(m,"reference"),cl.get("amount"));return db.update("UPDATE claim SET status='PAID' WHERE id=?",x);
 case "inspection.create":Auth.role(u,"REGULATOR");x=n(m,"caregiverId");workerScope(u,x);return db.insert("INSERT INTO inspection(caregiver_id,inspector_id,method,score,issue,rectification) VALUES(?,?,?,?,?,?)",x,u.id(),s(m,"method"),n(m,"score"),s(m,"issue"),s(m,"rectification"));
 case "inspection.close":Auth.role(u,"REGULATOR");x=n(m,"inspectionId");var ins=db.one("SELECT i.*,a.community_id FROM inspection i JOIN account a ON a.id=i.inspector_id WHERE i.id=? FOR UPDATE",x);if(id(ins,"community_id")!=u.community())throw new Forbidden();return db.update("UPDATE inspection SET status='CLOSED',result=? WHERE id=?",s(m,"result"),x);
 case "maintenance.run":Auth.role(u,"ADMIN");db.call("expire_plans");db.call("escalate_events");return "到期及超时检查完成";
 default:throw new Rule("未知业务操作");
 }
 }
}
